/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb7", fn: function () { return String(dma_ListApplComDetail.get("dpFromEmpCnt")) + " 명"; } },
        { childId: "__rb13", fn: function () { return String(dma_ListApplComDetail.get("dpFromAcntclsMmdd")) + " 월"; } },
        { childId: "__rb21", fn: function () { return String(dma_ListApplComDetail.get("dpFromLgshrhdRto")) + " %"; } },
        { childId: "__rb24", fn: function () { return String(dma_ListApplComDetail.get("dpFromListShrs")) + " 주"; } },
        { childId: "__rb25", fn: function () { return String(dma_ListApplComDetail.get("pubofrSchdlShrs")) + " 주"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("dialog-loading").setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71110.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnPopClose
 * @description fn Pop Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPopClose = function () {
    $c.win.closePopup();
};
